    if (idx >= arr.length || capacity <= 0) return 0;
    int without = knapsackRec(arr, idx + 1, capacity);
    int with = 0;
    if (arr[idx] <= capacity) with = arr[idx] + knapsackRec(arr, idx + 1, capacity - arr[idx]);
    return Math.max(with, without);
}
